<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\Gateway;

use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\UserFederatedIdentity;

class UserFederatedIdentityCursor
{
    public const string SUBJECT_ASC = 'subject';
    public const string SUBJECT_DESC = '-subject';

    public function __construct(
        private int $limit,
        private ?string $sinceUid = null,
        private ?string $sinceSubject = null,
        private ?array $order = null,
    ) {
    }
    public function next(UserFederatedIdentity $userFederatedIdentity, ?int $size): UserFederatedIdentityCursor
    {
        $next = clone $this;
        $next->sinceUid = $userFederatedIdentity->uid();
        $next->sinceSubject = $userFederatedIdentity->getSubject();
        $next->limit = $size ?? $this->limit;
        return $next;
    }
    public function limit(): int
    {
        return $this->limit;
    }
    public function withLimit(int $limit): UserFederatedIdentityCursor
    {
        $next = clone $this;
        $next->limit = $limit;
        return $next;
    }
    public function sinceUid(): ?string
    {
        return $this->sinceUid;
    }
    public function sinceSubject(): ?string
    {
        return $this->sinceSubject;
    }
    public function order(): ?array
    {
        return $this->order;
    }
}
